sys_script_include.script:
var ClinicalTaskService = Class.create();

ClinicalTaskService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Clinical Task exists.
     *
     * @param {String} taskSysId
     * @return {Boolean}
     */
    taskExists: function(taskSysId) {

        if (this.validationUtils.isEmpty(taskSysId)) {
            return false;
        }

        var task = new GlideRecord(
            'x_2130921_caresy_0_clinical_task'
        );

        if (!task.isValid()) {
            gs.error(
                'ClinicalTaskService: Clinical Task table is invalid.'
            );
            return false;
        }

        return task.get(taskSysId);
    },

    /**
     * Retrieve a Clinical Task.
     *
     * @param {String} taskSysId
     * @return {GlideRecord|null}
     */
    getTask: function(taskSysId) {

        if (this.validationUtils.isEmpty(taskSysId)) {
            return null;
        }

        var task = new GlideRecord(
            'x_2130921_caresy_0_clinical_task'
        );

        if (!task.isValid()) {
            gs.error(
                'ClinicalTaskService: Clinical Task table is invalid.'
            );
            return null;
        }

        if (task.get(taskSysId)) {
            return task;
        }

        return null;
    },

    /**
     * Check whether a Clinical Task is currently active.
     *
     * @param {String} taskSysId
     * @return {Boolean}
     */
    isTaskActive: function(taskSysId) {

        var task = this.getTask(taskSysId);

        if (!task) {
            return false;
        }

        return task.getValue('active') == '1';
    },

    type: 'ClinicalTaskService'
};
